import json, re

def classify(o):
    m = re.findall(r"<answer>(.*?)</answer>", o, re.DOTALL)
    if m:
        expr = m[-1].strip()
        expr = expr.replace("\\times", "*").replace("\\div", "/").replace("×", "*").replace("÷", "/")
        if "=" in expr:
            expr = expr.split("=")[0].strip()
        if re.fullmatch(r"[0-9+\-*/()\s]+", expr or " "):
            try:
                val = eval(expr)
                return ('parse_ok', expr, val)
            except Exception:
                return ('eval_err', expr, None)
        return ('bad_chars', expr[:40], None)
    if '<answer>' in o:
        return ('unclosed', None, None)
    return ('no_tag', None, None)

for step in [0, 45]:
    from collections import Counter
    c = Counter()
    with open(f'/workspace/results/grpo_countdown/val_generations/{step}.jsonl') as f:
        rows = [json.loads(l) for l in f]
    for r in rows:
        cat, _, _ = classify(r['output'])
        c[cat] += 1
    print(f'step {step}: {dict(c)}')

