        total_multi += 1
        # score using FIRST tag
        first = score_countdown(o.replace(tags[-1], 'PLACEHOLDER_LAST', 1), r['gts'])  # crude
        # simpler: build strings with only first / only last tag
        s_first = f"<answer>{tags[0]}</answer>"
        s_last = f"<answer>{tags[-1]}</answer>"
