def repeat(self, repeat_times=2, interleave=True):
    """
    Repeat the batch data a specified number of times.

    Args:
        repeat_times (int): Number of times to repeat the data.
        interleave (bool): Whether to interleave the repeated data.

    Returns:
        DataProto: A new DataProto with repeated data.
    """
    if self.batch is not None:
        if interleave:
            # Interleave the data
            repeated_tensors = {
                key: tensor.repeat_interleave(repeat_times, dim=0) for key, tensor in self.batch.items()
            }
        else:
            # Stack the data
            repeated_tensors = {
                key: tensor.unsqueeze(0).expand(repeat_times, *tensor.shape).reshape(-1, *tensor.shape[1:])
                for key, tensor in self.batch.items()
            }

        repeated_batch = TensorDict(
            source=repeated_tensors,
            batch_size=(self.batch.batch_size[0] * repeat_times,),
        )
    else:
        repeated_batch = None

    repeated_non_tensor_batch = {}
    for key, val in self.non_tensor_batch.items():
        if interleave:
            repeated_non_tensor_batch[key] = np.repeat(val, repeat_times, axis=0)
        else:
            repeated_non_tensor_batch[key] = np.tile(val, (repeat_times,) + (1,) * (val.ndim - 1))

    return type(self)(
        batch=repeated_batch,
        non_tensor_batch=repeated_non_tensor_batch,
        meta_info=self.meta_info,
    )

def unfold_column_chunks(self, n_split: int, split_keys: Optional[list[str]] = None):
    """Split along the second dim into `n_split`, unfold it to the first dim (batch dim)
    Useful in passing grouped tensors that doesn't want to be shuffled in dataset.
    keys not in split_keys are repeated to match the shape
    Note that if the `split_keys` is not provided, it will repeat all the keys in the second dim.
    """
    if self.batch is not None:
        unfolded_batch = {}
        for key in self.batch.keys():
            if key in split_keys if split_keys is not None else False:
                shape = list(self.batch[key].shape)
                shape[0] = self.batch[key].shape[0] * n_split
                shape[1] = self.batch[key].shape[1] // n_split
                unfolded_batch[key] = self.batch[key].reshape(*shape)
            else:
                unfolded_batch[key] = torch.repeat_interleave(self.batch[key], n_split, dim=0)

        else:
            logger.info(f"CANN version {cann_version} is below 8.3.RC1")
    else:
        logger.info(f"Software version {software_version} is below 25.3.rc1")

    return False


def is_support_ipc() -> bool:
    """Check if the device supports IPC (Inter-Process Communication).

    For GPU devices, always returns True.
    For NPU devices, checks the software version and CANN toolkit version
    to determine if IPC is supported.

    Returns:
        bool: True if IPC is supported, False otherwise.
    """
    # If CUDA is available, it's a GPU device
    if is_cuda_available:
        return True

    # For NPU devices, check the software version and CANN toolkit version
    if is_npu_available:
        try:
            software_version, cann_version = get_npu_versions()
            return check_ipc_version_support(software_version, cann_version)

        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Failed to execute npu-smi command: {e}") from e
        except Exception as e:
            raise RuntimeError(f"Error checking IPC support: {e}") from e

    # For other devices (CPU), return False
    return False
